// Layer 1: slow drifting satin grain, sweeping along the X axis of the face
float g1 = gln_simplex(p * vec3(10.0, 1.8, 4.0) + t * vec3(0.04, 0.0, 0.0));
float g2 = gln_simplex(p * vec3(30.0, 0.6, 9.0) - t * vec3(0.16, 0.0, 0.0));

// Normalize both into 0..1 and blend into a soft flowing value
float satin = gln_normalize(g1) * 0.5 + gln_normalize(g2) * 0.4;

// Layer 2: subtle cool-white spectral sheen where the grain peaks,
// slightly enhanced toward the upper-left (typical highlight zone)
float shine = smoothstep(0.55, 1.0, satin) * (0.5 + 0.4 * smoothstep(0.0, 1.0, n.x));
vec3 spectral = mix(base, base * vec3(1.0, 1.01, 1.02), shine * 0.6);

// Final albedo: keep the platinum mostly intact, add thin luminous banding
return spectral * (0.97 + 0.03 * gln_normalize(g1));

// M — machined satin, travelling signal
float g = gln_simplex(p.xy * vec2(24.0, 32.0) + vec2(t * 0.04, 0.0));
g = 0.5 * (g + 1.0);
float brightness = 0.99 + 0.025 * g;

// Machined vertical brush ridges, slowly travelling
float b = sin(p.y * 26.0 - t * 0.6);
b = smoothstep(0.485, 0.515, abs(b - 0.5));
float striation = 0.013 * b;

// Gentle travelling color drift across the face
float d = gln_simplex(vec3(p.xy * 0.3, t * 0.09));
d = 0.5 * (d + 1.0);
float k = 0.35 + 0.55 * d;
vec3 shift = vec3(0.0, 0.0, 0.0) * (1.0 - k) + mix(base * vec3(0.0, 0.025, 0.05), vec3(0.0), k * 0.7);

// Central notch: machined tick row + soft cyan pulse
float notch = smoothstep(-0.02, 0.0, p.y + 0.42) * smoothstep(0.22, 0.48, -(p.y + 0.42)) * smoothstep(0.11, 0.0, abs(p.x)) * (0.5 + 0.5 * sin(t * 2.5));
float notchOut = 0.02 * notch;

vec3 outAlbedo = base * (brightness + striation) + vec3(notchOut);
return outAlbedo;

// D designer — flowing satin face: slow wave sweep + fine grain + subtle edge fringe
float wave = smoothstep(-0.45, 0.55, sin(p.y * 2.2 + t * 0.35) * 0.5 + 0.5);
float grain = gln_normalize(gln_simplex(p.zx * vec2(10.0, 12.0) + t * 0.12));
float fringe = smoothstep(0.62, 0.92, abs(p.z) * 3.2 / 0.6);
return base * (0.945 + 0.022 * grain + 0.055 * wave + 0.035 * fringe);

