vec3 satin_grain(vec3 p, float t){
    vec2 uv = p.xy * vec2(9.0, 3.5);
    float a = atan(uv.y, uv.x);
    vec2 grain = uv + vec2(-cos(a*1.7)*3.0, sin(a*1.4)*3.0);
    return gln_simplex(grain + vec2(t * 0.06, t * 0.015)) * 0.5 + 0.5;
}

