// Layer 1: directional satin grain that flows along the chevron
vec2 baseUV = p.xy * vec2(9.0, 3.0);
float grain = gln_simplex(baseUV + vec2(t * 0.055, t * 0.012));
float grainSoft = smoothstep(0.35, 0.65, abs(grain));
float grainDir = gln_normalize(gln_simplex(baseUV * vec2(2.2, 0.7) + vec3(t * 0.09, t * 0.02, 0.0)) - 0.5) * 0.18;

// Layer 2: soft rim shimmer along the arrow's edges, independent of vertex position
vec3 rim = pow(max(0.0, dot(n, vec3(0.0, 1.0, -1.0))), 2.0) * 0.45;
rim *= smoothstep(0.55, 1.0, length(p.xy) / 5.0);

// Layer 3: faint linear sheen stripe following the arrow's diagonal
float sheen = smoothstep(-0.4, 0.2, dot(normalize(p), normalize(vec3(0.7, 0.5, 0.0)))) * 0.12 * (1.0 - smoothstep(0.0, 2.0, length(p.z + 0.3)));

return base * (0.97 + grainDir + grainSoft * 0.03 + rim * 0.18 + sheen * 0.25);

// AMD atmospheric ground: deep near-black base with a faint, slow-moving cyan field
float cx = uv.x - 0.5;
float cy = uv.y - 0.5;
float d = length(vec2(cx * 2.4, cy * 1.3));
float grad = smoothstep(0.0, 1.0, max(0.0, 1.0 - d * 1.25));

// slow spatial noise, subtle color shift toward cyan
vec2 s = vec2(uv.x * 3.2 + t * 0.018, uv.y * 2.2);
float n = gln_normalize(gln_simplex(s) * 0.45) * 0.6;
vec3 base = vec3(0.0045, 0.0065, 0.010) + vec3(n * 0.0012, n * 0.0018, n * 0.0025);

// a single very-faint horizon band under the dashboard level
float band = smoothstep(-0.14, 0.15, cy + 0.12);
band *= 0.38;
base += vec3(band * 0.0014, band * 0.002, band * 0.0028);

return base * grad;
